}

function draw() {
	sh.setUniform("u_time", millis()/200);
	rect(-width/2,-height/2,width,height);
}

function mousePressed(){
// prevents mouse press from registering twice
  if (millis() - lapse > 500){
    save('pix.jpg');
    lapse = millis();
  } 
