var vert = `
		precision highp float;

    // attributes, in
    attribute vec3 aPosition;
    attribute vec3 aNormal;
    attribute vec2 aTexCoord;

    // attributes, out
    varying vec3 var_vertPos;
    varying vec3 var_vertNormal;
    varying vec2 var_vertTexCoord;
		varying vec4 var_centerGlPosition;//原点

    // matrices
    uniform mat4 uModelViewMatrix;
    uniform mat4 uProjectionMatrix;
    uniform mat3 uNormalMatrix;
		uniform float u_time;


    void main() {
      vec3 pos = aPosition;
			vec4 posOut = uProjectionMatrix * uModelViewMatrix * vec4(pos, 1.0);
      gl_Position = posOut;

      // set out value
      var_vertPos      = pos;
      var_vertNormal   =  aNormal;
      var_vertTexCoord = aTexCoord;
			var_centerGlPosition = uProjectionMatrix * uModelViewMatrix * vec4(0., 0., 0.,1.0);
    }
`;


var frag = `

precision highp float;

#define PI 3.14159265359

uniform vec2 u_resolution;
uniform vec2 u_mouse;
uniform float u_time;

vec3 rotate(vec3 p, float angle, vec3 axis){
    vec3 a = normalize(axis);
    float s = sin(angle);
    float c = cos(angle);
    float r = 1.0 - c;
    mat3 m = mat3(
        a.x * a.x * r + c,
        a.y * a.x * r + a.z * s,
        a.z * a.x * r - a.y * s,
        a.x * a.y * r - a.z * s,
        a.y * a.y * r + c,
        a.z * a.y * r + a.x * s,
        a.x * a.z * r + a.y * s,
        a.y * a.z * r - a.x * s,
        a.z * a.z * r + c
    );
    return m * p;
}


vec3 opTwist( vec3 p, float k)
{
    float c = cos(k*p.y);
    float s = sin(k*p.y);
    mat2  m = mat2(c,-s,s,c);
    vec3  q = vec3(m*p.xz,p.y);
    return q;
}

//sphere
float sdSphere( vec3 p, float s )
{
  return length(p)-s;
}

//Torus
float sdTorus( vec3 p, vec2 t )
{    
  vec2 q = vec2(length(p.xz)-t.x,p.y);
  return length(q)-t.y;
}


float sdBox( vec3 p, vec3 b )
{
  vec3 q = abs(p) - b;
  return length(max(q,0.0)) + min(max(q.x,max(q.y,q.z)),0.0);
}


float sdRoundBox( vec3 p, vec3 b, float r )
{
  vec3 q = abs(p) - b;
  return length(max(q,0.0)) + min(max(q.x,max(q.y,q.z)),0.0) - r;
}


//texture

float random (in vec2 st) {
   	highp float a = 12.9898;
    highp float b = 78.233;
    highp float c = 43758.5453;
    highp float dt= dot(st.xy ,vec2(a,b));
    highp float sn= mod(dt,3.14);
    return fract(sin(sn) * c);
}

float noise(vec2 st) {
    vec2 i = vec2(0.);
		i = floor(st);
    vec2 f = vec2(0.);
		f = fract(st);
    vec2 u =  vec2(0.);
		u = f*f*(3.0-2.0*f);
    return mix( mix( random( i + vec2(0.0,0.0) ),
                     random( i + vec2(1.0,0.0) ), u.x),
                mix( random( i + vec2(0.0,1.0) ),
                     random( i + vec2(1.0,1.0) ), u.x), u.y);
}


//combined Function
float dist_func(vec3 p)
{
    float span = 90.0;
    float angleOffset =  random(floor(p.xz/span)) * PI * 2.0 ;
    vec3 pm = mod(p, span) - span/2.0;
    vec3 pOff = vec3(sin(u_time*5.0 + p.z*0.1)*span*0.05,sin(u_time*1.0 + p.z*0.1)*span*0.05,0.0);
   	float weight = 0.05*span;
    float size = span*0.5;
    float rbDist1 = sdBox(pm + pOff,vec3( weight,  weight, size));

    return rbDist1;
}

vec3 getNormal(vec3 pos)
{
    float ep = 0.001;
    return normalize(vec3(
        dist_func(pos) - dist_func(vec3(pos.x - ep, pos.y, pos.z)),
        dist_func(pos) - dist_func(vec3(pos.x, pos.y - ep, pos.z)),
        dist_func(pos) - dist_func(vec3(pos.x, pos.y, pos.z - ep))
    ));
}



//variables
vec3 lightDir = normalize(vec3(0.0,1.0,0.0));
vec3 bgCol = vec3(1.000,1.000,1.000);
vec3 objCol = vec3(0.284,1.000,1.000);
vec3 shadowCol = vec3(0.502,0.741,0.980);



float grid(vec2 uv, float num)
{
    float w = 0.2;
    uv *= num;
    uv = fract(uv);
    float v = uv.x >= 0.5-w*0.5 && uv.x < 0.5+w*0.5 || uv.y >= 0.5-w*0.5 && uv.y < 0.5+w*0.5 ? 1. : 0.;
    return v;
}



void main() {
   vec2 pos = (gl_FragCoord.xy*2.0 - u_resolution.xy)/max(u_resolution.x,u_resolution.y);

    //camera
    float angleY = 0.0;
    float angleX = 0.0;
    vec3 camera_dir = rotate(rotate(vec3(0.0, 0.0, 1.0), angleY, vec3(0.0,1.0,0.0)), angleX, vec3(1.0,0.0,0.0)); 
    vec3 cameraPos = vec3(0.0, 0.0, 10.0+u_time*0.0) + camera_dir*u_time*0.0;
    vec3 camera_up = rotate(rotate(vec3(0.0, 1.0, 0.0), angleY, vec3(0.0,1.0,0.0)), angleX, vec3(1.0,0.0,0.0)); 
    vec3 camera_side = cross(camera_up, camera_dir); 

    //ray
	 vec3 n = vec3(0,0,0);
    float d = 0.0;
    vec3 rayDir = normalize(pos.x * camera_side + pos.y * camera_up + camera_dir); 
    vec3 currentPos = cameraPos;
    for(int i = 0; i < 160; i++){
       d = dist_func(currentPos);
       if (d < 0.001)
       {
       	 n = getNormal(currentPos);
         break;
       }
       currentPos += rayDir * d;
   }

   //diffuse
    float diff = d < 0.001 ? dot(n, lightDir) : -1.0 ;
    diff = (diff / 2.0) + 0.5;
    vec3 diifCol = diff * objCol + (1.0- diff)* mix(objCol, objCol*(bgCol-0.5), 0.6);
    vec3 col = d < 0.001 ? vec3(diifCol) : bgCol;
    float noise = random(pos);
    float noisedDiff =  step(noise,diff);
    col *= noisedDiff + vec3(1.0 - noisedDiff) * shadowCol;


    //fog
    float deapth = currentPos.z-cameraPos.z;
    float minDep = 50.0;
    float maxDep = 650.0;
    float fogRatio = min((max(deapth, minDep)-minDep) / (maxDep - minDep), 1.0);
    col = mix(col, bgCol, fogRatio);

    gl_FragColor = vec4(vec3(col), 1.0);
}

`;

